export function parseM78RecipeInput(v:unknown):M78RecipeInput{const r=v as M78RecipeInput;check(r&&['inspect','run'].includes(r.mode)&&/^m78_ops_recipe_[a-z0-9_]+$/.test(r.database)&&r.companyId===COMPANY,'Fixed fresh recipe database/company required.');check(r.actorIds&&Object.keys(r.actorIds).sort().join(',')==='manager1,manager2,member'&&Object.values(r.actorIds).every(id=>uuid.test(id))&&new Set(Object.values(r.actorIds)).size===3,'Three distinct retained actor IDs required.');for(const key of ['migrationSha256','recipeSha256','runnerSha256']as const)check(digest.test(r[key]),'Exact reviewed source hashes required.');if(r.mode==='run'){check(digest.test(r.baselineRowsSha256)&&Array.isArray(r.reviewedSourcePins)&&r.reviewedSourcePins.length>3,'Reviewed source closure and baseline required.');check(Array.isArray(r.provenancePins)&&r.provenancePins.length>=3&&r.provenancePins.every(p=>typeof p.path==='string'&&digest.test(p.sha256))&&new Set(r.provenancePins.map(p=>p.path)).size===r.provenancePins.length,'Reviewed backup/restore/upgrade provenance pins required.');const local=relative(resolve('.'),resolve(r.journalPath)).replaceAll('\\','/');check(/^(\.superpowers|\.tmp)\/m78-recipe-[a-z0-9_-]+\.jsonl$/.test(local),'New bounded workspace journal path required.');}return r}
export const M78_RECIPE_RESOLVER_PINS=['package.json','tsconfig.base.json','packages/neuvetra-database/package.json','packages/neuvetra-database/tsconfig.json','apps/site-api/package.json','apps/site-api/tsconfig.json','config/typescript/api.json','apps/site-web/package.json','apps/site-web/tsconfig.json','apps/site-web/tsconfig.app.json','apps/site-web/tsconfig.node.json','config/typescript/web.json','config/typescript/vite.json']as const;
export async function m78RecipeSourcePins(){const files=new Set(['tools/staging/m78-recipe-rehearsal.ts','bun.lock',...M78_RECIPE_RESOLVER_PINS]),pending=['tools/staging/m78-recipe-rehearsal.ts'];while(pending.length){const file=pending.pop()!,text=await readFile(file,'utf8');for(const match of text.matchAll(/\b(?:from\s*|import\s*\(\s*|import\s*)['"]([^'"]+)['"]/g)){const name=match[1]!;if(!name.startsWith('.'))continue;const base=resolve(dirname(file),name);let target:string|undefined;for(const p of [base,base+'.ts',base+'.tsx',resolve(base,'index.ts')]){try{await readFile(p);target=p;break}catch{}}check(target,'Unresolved rehearsal import.');const path=relative(resolve('.'),target).replaceAll('\\','/');check(!path.startsWith('../')&&!path.startsWith('/')&&!path.includes(':'),'Rehearsal import outside workspace.');if(!files.has(path)){files.add(path);if(/\.tsx?$/.test(path))pending.push(path)}}}for(const m of await readMigrationManifest())files.add('packages/neuvetra-database/src/migrations/'+m.name);return Promise.all([...files].sort().map(async path=>({path,sha256:sha(await readFile(path))})))}
const FAMILIES=['corporate_inventory','stationary_gas','mobile_diesel','controlled_fleet','stationary_diesel','stationary_equipment','fugitive','scope1']
