export async function m78RecipeRows(c:WorkspaceConnection):Promise<Rows>{const tables=(await c.query<{name:string}>("select table_name name from information_schema.tables where table_schema='neuvetra' and table_type='BASE TABLE' order by table_name")).rows,out:Rows={};for(const {name}of tables){check(/^[a-z0-9_]+$/.test(name),'Unsafe table.');out[name]=(await c.query<{row:string}>(`select neuvetra.m67_canonical(to_jsonb(t))row from neuvetra.${name} t order by neuvetra.m67_canonical(to_jsonb(t)) collate "C"`)).rows.map(r=>r.row)}return out}
const normalizeHead=(name:string,row:string)=>{const v=JSON.parse(row);if(HEADS.has(name)&&v.company_id===COMPANY){delete v.version_id;delete v.revision}return canonical(v)}
