const tokens=Object.fromEntries(Object.entries(input.actorIds).map(([role,id])=>['synthetic-recipe-'+role,id])),validateUser=async(token:string)=>tokens[token]?{id:tokens[token],phone:null,email:null,fullName:null}:null,deps={database,validateUser,origin:ORIGIN},handlers:{[path:string]:(r:Request)=>Promise<Response>}={'corporate-inventories':createCorporateInventoryRoutes(deps),'stationary-natural-gas':createM73Routes({...deps,authority:authorities.gas}),'mobile-diesel':createM74Routes({...deps,authority:authorities.mobile}),'controlled-fleet':createM75Routes({...deps,authority:authorities.mobile}),'stationary-equipment':createM76Routes({...deps,authorities:{gas:authorities.gas,diesel:authorities.diesel}}),'stationary-diesel':createM76Routes({...deps,authorities:{gas:authorities.gas,diesel:authorities.diesel}}),'fugitive-sources':createM77Routes({...deps,authority:authorities.fugitive}),'fugitive-population':createM77Routes({...deps,authority:authorities.fugitive}),'process-screen':createM78Routes({...deps,authorities,policy:M78_REVIEWED_POLICY}),'scope1-inventory':createM78Routes({...deps,authorities,policy:M78_REVIEWED_POLICY})},root='/workspace-api/workspace/'+COMPANY;
