const get=async(route:string,role:Role='manager1')=>{const r=await call(route,role);check(r.status===200,'Authorized GET failed.');return parseM78Json(r.text,10_000_000)},scope1=async()=>decodeScope1Register(await get(root+'/scope1-inventory'),COMPANY),decoders:any={'corporate-inventories':decodeCorporateVersion,'stationary-natural-gas':decodeGasVersion,'mobile-diesel':decodeMobileVersion,'stationary-diesel':decodeGeneratorVersion,'controlled-fleet':decodeFleetVersion,'stationary-equipment':decodeStationaryVersion,'fugitive-sources':decodeFugitiveVersion,'fugitive-population':decodeFugitiveVersion,'process-screen':decodeScope1Version,'scope1-inventory':decodeScope1Version};const seen=new Set<string>();
const post=async(name:string,route:string,role:string,request:unknown,expected=201)=>{stage=name;check(expected===201&&posts<38&&!seen.has(name)&&['manager1','manager2'].includes(role),'Single-use successful recipe write required.');check(route===root+'/scope1-inventory'||route===root+'/process-screen'||new RegExp('^'+root+'/(corporate-inventories|stationary-natural-gas|mobile-diesel|stationary-diesel|controlled-fleet|stationary-equipment|fugitive-sources|fugitive-population|process-screen|scope1-inventory)/[a-f0-9-]{36}/(versions|reviews|reports)$').test(route),'Fixed recipe write route refused.');await append('post_intent',{name,route,role,expected,request});posts++;seen.add(name);const response=await call(route,role as Role,request);await append('post_outcome',{name,route,role,status:response.status,responseSha256:sha(response.bytes),byteLength:response.bytes.length});check(response.status===201,'Recipe POST refused; inspect frozen journal, never retry.');const raw:any=parseM78Json(response.text,10_000_000),family=route.slice(root.length+1).split('/')[0]!;let decoded:any;if(route.endsWith('/reviews')){const exact=await decoders[family](await get(route.replace(/\/reviews$/,'/versions/'+raw.versionId)),COMPANY);check(same((exact.version??exact).review,raw),'Exact retained review mismatch.');decoded=raw}else if(route.endsWith('/reports')){decoded=await decodeScope1Report(raw,COMPANY);check(same(decoded,await decodeScope1Report(await get(route+'/'+raw.id),COMPANY)),'Exact retained report mismatch.');for(const [operation,value]of [['download',decoded.html],['snapshot',decoded.snapshotJson]]){const read=await call(route+'/'+raw.id+'/'+operation,'member');check(read.status===200&&read.text===value,'Report download mismatch.')}}else{decoded=await decoders[family](raw,COMPANY);const v=decoded.version??decoded,base=route.endsWith('/versions')?route.slice(0,-9):route+'/'+(v.streamId??v.worksheetId??v.rosterId??v.inventoryId);const exact=await decoders[family](await get(base